const DB_NAME   = "financeTrackerDB";
const STORE_NAME = "entries";
const DB_VERSION = 2; // bumped for budget store

// ── Open / upgrade DB ──────────────────────────────────────────────
export function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);
    request.onerror         = e => reject(e.target.error);
    request.onsuccess       = e => resolve(e.target.result);
    request.onupgradeneeded = e => {
      const db = e.target.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: "id" });
      }
      // new store for monthly budgets
      if (!db.objectStoreNames.contains("budgets")) {
        db.createObjectStore("budgets", { keyPath: "key" }); // key = "YYYY-MM:Category"
      }
    };
  });
}

// ── Entries ────────────────────────────────────────────────────────
export async function loadEntries() {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const store = db.transaction(STORE_NAME, "readonly").objectStore(STORE_NAME);
    const req   = store.getAll();
    req.onsuccess = () => resolve(req.result);
    req.onerror   = e => reject(e.target.error);
  });
}

export async function saveEntry(entry) {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const store = db.transaction(STORE_NAME, "readwrite").objectStore(STORE_NAME);
    const req   = store.put(entry);
    req.onsuccess = () => resolve();
    req.onerror   = e => reject(e.target.error);
  });
}

// updateEntry = same as saveEntry (put is upsert), exposed separately for clarity
export async function updateEntry(entry) {
  return saveEntry(entry);
}

export async function deleteEntry(id) {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const store = db.transaction(STORE_NAME, "readwrite").objectStore(STORE_NAME);
    const req   = store.delete(id);
    req.onsuccess = () => resolve();
    req.onerror   = e => reject(e.target.error);
  });
}

export async function clearEntries() {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const store = db.transaction(STORE_NAME, "readwrite").objectStore(STORE_NAME);
    const req   = store.clear();
    req.onsuccess = () => resolve();
    req.onerror   = e => reject(e.target.error);
  });
}

// ── Budgets ────────────────────────────────────────────────────────
export async function loadBudgets() {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const store = db.transaction("budgets", "readonly").objectStore("budgets");
    const req   = store.getAll();
    req.onsuccess = () => resolve(req.result); // [{key, amount}]
    req.onerror   = e => reject(e.target.error);
  });
}

export async function saveBudget(key, amount) {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const store = db.transaction("budgets", "readwrite").objectStore("budgets");
    const req   = store.put({ key, amount });
    req.onsuccess = () => resolve();
    req.onerror   = e => reject(e.target.error);
  });
}

export async function deleteBudget(key) {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const store = db.transaction("budgets", "readwrite").objectStore("budgets");
    const req   = store.delete(key);
    req.onsuccess = () => resolve();
    req.onerror   = e => reject(e.target.error);
  });
}