import React, { useState, useEffect, useCallback, useMemo } from "react";
import SplashScreen from "./components/SplashScreen";
import EntryForm    from "./components/EntryForm";
import Filter       from "./components/Filter";
import Summary      from "./components/Summary";
import Dashboard    from "./components/Dashboard";
import EntriesList  from "./components/EntriesList";
import BankTransferForm from "./components/BankTransferForm";
import Budget       from "./components/Budget";
import ChatAI       from "./components/ChatAI";

import {
  loadEntries, saveEntry, updateEntry,
  deleteEntry as deleteDBEntry,
  clearEntries as clearDBEntries,
  loadBudgets, saveBudget, deleteBudget,
} from "./utils/indexedDB";

const NAV_ITEMS = [
  { id: "overview",  label: "Overview",  icon: "📊" },
  { id: "add",       label: "Add",       icon: "➕" },
  { id: "list",      label: "Entries",   icon: "📋" },
  { id: "transfer",  label: "Transfer",  icon: "↔️"  },
  { id: "budget",    label: "Budget",    icon: "🎯" },
];

export default function App() {
  const [splash,      setSplash]      = useState(() => {
    // Show splash only once per session
    return !sessionStorage.getItem("splashShown");
  });
  const [entries,     setEntries]     = useState([]);
  const [budgets,     setBudgets]     = useState([]);   // [{key, amount}]
  const [filter,      setFilter]      = useState({ from: "", to: "" });
  const [showChat,    setShowChat]    = useState(false);
  const [activeTab,   setActiveTab]   = useState("overview");
  const [showConfirm, setShowConfirm] = useState(false);
  const [clearing,    setClearing]    = useState(false);
  const [theme,       setTheme]       = useState(() => localStorage.getItem("ft_theme") || "dark");
  const [editingEntry,setEditingEntry]= useState(null); // entry being edited
  const [toasts,      setToasts]      = useState([]);   // [{id,msg,type}]

  // ── Theme ─────────────────────────────────────────────────────────
  useEffect(() => {
    document.documentElement.setAttribute("data-theme", theme);
    localStorage.setItem("ft_theme", theme);
  }, [theme]);

  // ── Load data ─────────────────────────────────────────────────────
  useEffect(() => {
    loadEntries().then(d => setEntries(d));
    loadBudgets().then(d => setBudgets(d));
  }, []);

  // ── Toast helper ──────────────────────────────────────────────────
  const showToast = useCallback((msg, type = "success") => {
    const id = Date.now();
    setToasts(prev => [...prev, { id, msg, type }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 3200);
  }, []);

  // ── Smart alerts (auto budget overspend detection) ────────────────
  const smartAlerts = useMemo(() => {
    const alerts = [];
    const now   = new Date();
    const curMY = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,"0")}`;

    // Check each budget for the current month
    budgets.forEach(b => {
      const [bMY, category] = b.key.split(":");
      if (bMY !== curMY) return;
      const spent = entries
        .filter(e => e.type === "expense" && e.category === category && e.date?.startsWith(curMY))
        .reduce((s,e) => s + e.amount, 0);
      const pct = (spent / b.amount) * 100;
      if (pct >= 100)  alerts.push({ type:"danger",  msg:`🚨 ${category} budget exceeded! ₹${spent.toFixed(0)} / ₹${b.amount}` });
      else if (pct >= 80) alerts.push({ type:"warning", msg:`⚠️ ${category} at ${pct.toFixed(0)}% of budget` });
    });

    // Savings rate alert
    const curMonthIncome  = entries.filter(e => e.type==="income"  && e.date?.startsWith(curMY) && e.category!=="Bank Transfer").reduce((s,e)=>s+e.amount,0);
    const curMonthExpense = entries.filter(e => e.type==="expense" && e.date?.startsWith(curMY) && e.category!=="Bank Transfer").reduce((s,e)=>s+e.amount,0);
    if (curMonthIncome > 0 && curMonthExpense > curMonthIncome * 0.9)
      alerts.push({ type:"warning", msg:`⚠️ This month you spent ${((curMonthExpense/curMonthIncome)*100).toFixed(0)}% of income!` });

    return alerts;
  }, [entries, budgets]);

  const isDark = theme === "dark";

  // ── CRUD ──────────────────────────────────────────────────────────
  const handleAddEntry = async (entry) => {
    await saveEntry(entry);
    setEntries(prev => [...prev, entry]);
    showToast("Entry added ✓");
  };

  const handleUpdateEntry = async (entry) => {
    await updateEntry(entry);
    setEntries(prev => prev.map(e => e.id === entry.id ? entry : e));
    setEditingEntry(null);
    showToast("Entry updated ✓");
  };

  const handleDeleteEntry = async (id) => {
    await deleteDBEntry(id);
    setEntries(prev => prev.filter(e => e.id !== id));
    showToast("Entry deleted", "danger");
  };

  const handleBulkDelete = async (ids) => {
    await Promise.all(ids.map(id => deleteDBEntry(id)));
    setEntries(prev => prev.filter(e => !ids.includes(e.id)));
    showToast(`${ids.length} entries deleted`, "danger");
  };

  const handleTransfer = (transfer) => {
    const newEntries = [
      { id: transfer.id + "-from", type:"expense", amount:transfer.amount, bank:transfer.fromBank, description:`Transfer to ${transfer.toBank}`,   category:"Bank Transfer", date:transfer.date },
      { id: transfer.id + "-to",   type:"income",  amount:transfer.amount, bank:transfer.toBank,   description:`Transfer from ${transfer.fromBank}`, category:"Bank Transfer", date:transfer.date },
    ];
    newEntries.forEach(saveEntry);
    setEntries(prev => [...prev, ...newEntries]);
    showToast(`Transfer ₹${transfer.amount} done ✓`);
  };

  const handleSaveBudget = async (key, amount) => {
    await saveBudget(key, amount);
    setBudgets(prev => {
      const exists = prev.findIndex(b => b.key === key);
      if (exists >= 0) return prev.map((b,i) => i===exists ? {key,amount} : b);
      return [...prev, {key, amount}];
    });
    showToast("Budget saved ✓");
  };

  const handleDeleteBudget = async (key) => {
    await deleteBudget(key);
    setBudgets(prev => prev.filter(b => b.key !== key));
    showToast("Budget removed", "danger");
  };

  async function confirmClear() {
    try {
      setClearing(true);
      await clearDBEntries();
      setEntries([]);
      showToast("All data cleared", "danger");
    } catch(e) {
      alert("Failed to clear data.");
    } finally {
      setClearing(false);
      setShowConfirm(false);
    }
  }

  // ── Filtered entries for list tab ─────────────────────────────────
  const filteredEntries = useMemo(() => entries.filter(entry => {
    const d    = new Date(entry.date);
    const from = filter.from ? new Date(filter.from) : null;
    const to   = filter.to   ? new Date(filter.to)   : null;
    if (from && d < from) return false;
    if (to   && d > to)   return false;
    return true;
  }), [entries, filter]);

  // ── Tab content ───────────────────────────────────────────────────
  const renderTab = () => {
    switch(activeTab) {
      case "overview": return (
        <div className="fade-up">
          {smartAlerts.length > 0 && (
            <div style={{ marginBottom:14, display:"flex", flexDirection:"column", gap:7 }}>
              {smartAlerts.map((a,i) => (
                <div key={i} style={{
                  padding:"10px 16px", borderRadius:10, fontSize:13, fontWeight:600,
                  background: a.type==="danger" ? "rgba(252,129,129,0.12)" : "rgba(246,224,94,0.10)",
                  border: `1px solid ${a.type==="danger" ? "rgba(252,129,129,0.3)" : "rgba(246,224,94,0.3)"}`,
                  color: a.type==="danger" ? "var(--accent-red)" : "var(--accent-yellow)",
                  fontFamily:"'Syne',sans-serif",
                }}>{a.msg}</div>
              ))}
            </div>
          )}
          <Dashboard entries={entries} theme={theme} />
        </div>
      );
      case "add": return (
        <div className="fade-up">
          <EntryForm
            addEntry={handleAddEntry}
            editingEntry={editingEntry}
            updateEntry={handleUpdateEntry}
            onCancelEdit={() => setEditingEntry(null)}
          />
        </div>
      );
      case "transfer": return <div className="fade-up"><BankTransferForm addTransfer={handleTransfer} /></div>;
      case "list": return (
        <div className="fade-up">
          <Filter filter={filter} setFilter={setFilter} />
          <EntriesList
            entries={filteredEntries}
            deleteEntry={handleDeleteEntry}
            bulkDelete={handleBulkDelete}
            onEdit={entry => { setEditingEntry(entry); setActiveTab("add"); }}
          />
        </div>
      );
      case "budget": return (
        <div className="fade-up">
          <Budget entries={entries} budgets={budgets} onSave={handleSaveBudget} onDelete={handleDeleteBudget} />
        </div>
      );
      default: return null;
    }
  };

    // ── Splash screen — show once per session ─────────────────────────
  if (splash) {
    return (
      <SplashScreen
        onDone={() => {
          sessionStorage.setItem("splashShown", "1");
          setSplash(false);
        }}
      />
    );
  }


  return (
    <div style={{ minHeight:"100vh" }}>

      {/* ── HEADER ── */}
      <header className="app-header">
        <div className="app-header-inner">
          <div style={{ display:"flex", alignItems:"center", flexShrink:0 }}>
            <img src="./logo.svg" alt="Shivam Sharma Finance Tracker"
              style={{ height:38, maxWidth:180, objectFit:"contain",
                filter: isDark ? "brightness(5)" : "brightness(1)", transition:"filter 0.3s" }} />
          </div>

          <nav className="desktop-nav" style={{ display:"flex", gap:2 }}>
            {NAV_ITEMS.map(item => (
              <button key={item.id} onClick={() => setActiveTab(item.id)} style={{
                padding:"6px 13px", borderRadius:8, border:"none", cursor:"pointer",
                fontFamily:"'Syne',sans-serif", fontWeight:600, fontSize:12.5,
                background: activeTab===item.id ? "var(--bg-nav-active)" : "transparent",
                color: activeTab===item.id ? "var(--accent-green)" : "var(--text-secondary)",
                borderBottom: activeTab===item.id ? "2px solid var(--accent-green)" : "2px solid transparent",
                transition:"all 0.15s",
                position:"relative",
              }}>
                <span style={{ marginRight:4 }}>{item.icon}</span>{item.label}
                {/* Budget tab: show alert dot if any alerts */}
                {item.id==="budget" && smartAlerts.length>0 && (
                  <span style={{ position:"absolute", top:4, right:4, width:7, height:7, borderRadius:"50%", background:"var(--accent-red)", boxShadow:"0 0 6px var(--accent-red)" }} />
                )}
              </button>
            ))}
          </nav>

          <div style={{ display:"flex", gap:8, alignItems:"center" }}>
            <label className="theme-toggle" title={`Switch to ${isDark?"light":"dark"} mode`}>
              <input type="checkbox" checked={!isDark} onChange={() => setTheme(t => t==="dark"?"light":"dark")} />
              <span className="theme-track" />
              <span className="theme-thumb">{isDark ? "🌙" : "☀️"}</span>
            </label>
            <button onClick={() => setShowChat(s => !s)} className="desktop-actions" style={{
              padding:"6px 12px", borderRadius:8,
              border:`1px solid ${showChat ? "var(--accent-blue)" : "var(--border)"}`,
              background: showChat ? "rgba(99,179,237,0.12)" : "transparent",
              color:"var(--accent-blue)", cursor:"pointer", fontSize:12,
              fontFamily:"'Syne',sans-serif", fontWeight:600, display:"inline-flex", alignItems:"center", gap:5,
            }}>🤖 AI</button>
            <button onClick={() => setShowConfirm(true)} title="Clear all data" style={{
              width:34, height:34, borderRadius:8,
              border:"1px solid rgba(252,129,129,0.3)", background:"transparent",
              color:"var(--accent-red)", cursor:"pointer", fontSize:15,
              display:"flex", alignItems:"center", justifyContent:"center",
            }}>🗑</button>
          </div>
        </div>
      </header>

      {/* ── MAIN ── */}
      <main className="main-content">
        <Summary entries={entries} onTabChange={setActiveTab} />

        {showChat && <div className="fade-up" style={{ marginBottom:20 }}><ChatAI entries={entries} /></div>}

        <div style={{ display:"none" }} className="mobile-ai-btn">
          <button onClick={() => setShowChat(s=>!s)} style={{
            width:"100%", padding:"10px", borderRadius:10, marginBottom:16,
            background: showChat ? "rgba(99,179,237,0.15)" : "var(--bg-card)",
            border:`1px solid ${showChat ? "var(--accent-blue)" : "var(--border)"}`,
            color:"var(--accent-blue)", fontFamily:"'Syne',sans-serif", fontWeight:700, fontSize:13, cursor:"pointer",
          }}>🤖 {showChat ? "Hide AI" : "Open AI Assistant"}</button>
        </div>

        {renderTab()}
      </main>

      {/* ── BOTTOM NAV (mobile) ── */}
      <nav className="bottom-nav">
        <div className="bottom-nav-inner">
          {NAV_ITEMS.map(item => (
            <button key={item.id} className={`bnav-item ${activeTab===item.id?"active":""}`}
              onClick={() => setActiveTab(item.id)} style={{ position:"relative" }}>
              <span className="bnav-icon">{item.icon}</span>
              {item.label}
              {item.id==="budget" && smartAlerts.length>0 && (
                <span style={{ position:"absolute", top:2, right:8, width:7, height:7, borderRadius:"50%", background:"var(--accent-red)" }} />
              )}
            </button>
          ))}
          <button className={`bnav-item ${showChat?"active":""}`}
            onClick={() => setShowChat(s=>!s)}
            style={{ color: showChat ? "var(--accent-blue)" : "var(--text-muted)" }}>
            <span className="bnav-icon">🤖</span>AI
          </button>
        </div>
      </nav>

      {/* ── TOAST NOTIFICATIONS ── */}
      <div style={{ position:"fixed", bottom:90, right:16, zIndex:500, display:"flex", flexDirection:"column", gap:8, alignItems:"flex-end" }}>
        {toasts.map(t => (
          <div key={t.id} style={{
            padding:"10px 18px", borderRadius:10, fontSize:13, fontWeight:600,
            fontFamily:"'Syne',sans-serif",
            background: t.type==="danger" ? "rgba(229,62,62,0.92)" : t.type==="warning" ? "rgba(246,224,94,0.92)" : "rgba(72,187,120,0.92)",
            color: t.type==="warning" ? "#1a202c" : "#fff",
            boxShadow:"0 4px 18px rgba(0,0,0,0.35)",
            animation:"slideInRight 0.25s ease",
            backdropFilter:"blur(8px)",
          }}>{t.msg}</div>
        ))}
      </div>

      {/* ── CONFIRM MODAL ── */}
      {showConfirm && (
        <div className="confirm-backdrop" onClick={e => e.target===e.currentTarget && setShowConfirm(false)}>
          <div className="confirm-modal scale-in">
            <div style={{ textAlign:"center", fontSize:38, marginBottom:14 }}>⚠️</div>
            <h5 style={{ textAlign:"center", marginBottom:8 }}>Clear all data?</h5>
            <p style={{ textAlign:"center", color:"var(--text-secondary)", lineHeight:1.6 }}>
              Permanently removes all entries. This action <strong style={{ color:"var(--accent-red)" }}>cannot</strong> be undone.
            </p>
            <div style={{ display:"flex", gap:10, justifyContent:"center", marginTop:24 }}>
              <button className="btn btn-secondary" onClick={() => setShowConfirm(false)} disabled={clearing}>Cancel</button>
              <button className="btn btn-danger" onClick={confirmClear} disabled={clearing}>
                {clearing ? "Clearing…" : "Yes, clear all"}
              </button>
            </div>
          </div>
        </div>
      )}

      <style>{`
        @media (max-width: 768px) { .mobile-ai-btn { display: block !important; } }
        @keyframes slideInRight { from { opacity:0; transform:translateX(30px); } to { opacity:1; transform:translateX(0); } }
      `}</style>
    </div>
  );
}