import React, { useState, useEffect } from "react";
import Swal from "sweetalert2";

const BANKS = ["BOB", "ICICI", "CASH"];

const CATEGORIES = {
  income:       ["Salary", "Bonus", "Freelance", "Rental Income", "Interest", "Other"],
  expense:      ["Food", "Rent", "Travel", "Utilities", "Entertainment", "Healthcare", "Shopping", "Education", "Other"],
  investment:   ["Stocks", "Mutual Fund", "Fixed Deposit", "Gold", "Crypto", "Other"],
  borrow:       ["Personal", "Emergency", "Other"],
  borrowReturn: ["Return"],
};

const TYPE_META = {
  income:       { label:"Income",        icon:"📈", accent:"#68d391" },
  expense:      { label:"Expense",       icon:"📉", accent:"#fc8181" },
  investment:   { label:"Investment",    icon:"💼", accent:"#63b3ed" },
  borrow:       { label:"Borrow",        icon:"🤝", accent:"#b794f4" },
  borrowReturn: { label:"Borrow Return", icon:"↩️", accent:"#f6e05e" },
};

// Smart auto-descriptions per category
const AUTO_DESC = {
  Salary:"Monthly salary", Bonus:"Bonus received", Freelance:"Freelance payment",
  Food:"Food & groceries", Rent:"Monthly rent", Travel:"Travel expense",
  Utilities:"Electricity / Utilities", Entertainment:"Entertainment", Healthcare:"Medical expense",
  Shopping:"Shopping", Education:"Education fee",
  Stocks:"Stock purchase", "Mutual Fund":"SIP / Mutual Fund", "Fixed Deposit":"FD deposit",
  Gold:"Gold purchase", Crypto:"Crypto investment",
};

const QUICK_TEMPLATES = [
  { label:"💸 ATM Withdraw",   bank:"CASH", type:"expense",      desc:"Cash withdrawal (ATM)",  cat:"Other"   },
  { label:"💵 Cash Received",  bank:"CASH", type:"income",       desc:"Cash received",           cat:"Other"   },
  { label:"💰 Monthly Salary", bank:"BOB",  type:"income",       desc:"Monthly salary",          cat:"Salary"  },
  { label:"🍔 Food",           bank:"CASH", type:"expense",      desc:"Food & groceries",        cat:"Food"    },
  { label:"📈 SIP",            bank:"BOB",  type:"investment",   desc:"SIP / Mutual Fund",       cat:"Mutual Fund" },
];

export default function EntryForm({ addEntry, editingEntry, updateEntry, onCancelEdit }) {
  const isEditing = !!editingEntry;

  const [type,        setType]        = useState("expense");
  const [description, setDescription] = useState("");
  const [amount,      setAmount]      = useState("");
  const [category,    setCategory]    = useState("");
  const [bank,        setBank]        = useState(BANKS[0]);
  const [date,        setDate]        = useState(new Date().toISOString().split("T")[0]);
  const [note,        setNote]        = useState("");
  const [recurring,   setRecurring]   = useState(false);

  // Populate form when editing
  useEffect(() => {
    if (editingEntry) {
      setType(editingEntry.type || "expense");
      setDescription(editingEntry.description || "");
      setAmount(editingEntry.amount?.toString() || "");
      setCategory(editingEntry.category || "");
      setBank(editingEntry.bank || BANKS[0]);
      setDate(editingEntry.date || new Date().toISOString().split("T")[0]);
      setNote(editingEntry.note || "");
    }
  }, [editingEntry]);

  const resetForm = () => {
    setType("expense"); setDescription(""); setAmount("");
    setCategory(""); setBank(BANKS[0]);
    setDate(new Date().toISOString().split("T")[0]);
    setNote(""); setRecurring(false);
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!description.trim() || !amount || !category || !bank) {
      return Swal.fire({ icon:"error", title:"Missing fields", text:"Please fill all required fields",
        background:"var(--bg-surface)", color:"var(--text-primary)" });
    }
    const entry = {
      ...(isEditing ? editingEntry : {}),
      id: isEditing ? editingEntry.id : Date.now(),
      type, description: description.trim(), amount: parseFloat(amount),
      category, bank, date, note: note.trim(),
    };

    if (isEditing) {
      updateEntry(entry);
    } else {
      addEntry(entry);
      // If recurring, schedule next month reminder (store flag)
      if (recurring) {
        const nextDate = new Date(date);
        nextDate.setMonth(nextDate.getMonth() + 1);
        const nextEntry = { ...entry, id: Date.now()+1, date: nextDate.toISOString().split("T")[0], note:"(Recurring)" };
        setTimeout(() => addEntry(nextEntry), 100);
      }
      resetForm();
    }
  };

  const applyTemplate = (tpl) => {
    setBank(tpl.bank); setType(tpl.type); setDescription(tpl.desc); setCategory(tpl.cat);
  };

  const handleCategoryChange = (cat) => {
    setCategory(cat);
    if (!description && AUTO_DESC[cat]) setDescription(AUTO_DESC[cat]);
  };

  const { accent } = TYPE_META[type] || TYPE_META.expense;

  return (
    <div className="card" style={{ borderColor:`${accent}35` }}>
      <div className="card-header" style={{ background:`linear-gradient(135deg,${accent}1a,${accent}08)`, borderBottomColor:`${accent}22` }}>
        <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between" }}>
          <div style={{ display:"flex", alignItems:"center", gap:8 }}>
            <div style={{ width:8, height:8, borderRadius:"50%", background:accent, boxShadow:`0 0 8px ${accent}` }} />
            <h5 style={{ margin:0, color:accent }}>{isEditing ? "✏️ Edit Entry" : "➕ Add New Entry"}</h5>
          </div>
          {isEditing && (
            <button onClick={onCancelEdit} style={{ background:"rgba(252,129,129,0.15)", border:"1px solid rgba(252,129,129,0.3)", color:"var(--accent-red)", borderRadius:8, padding:"4px 12px", cursor:"pointer", fontSize:12, fontFamily:"'Syne',sans-serif", fontWeight:600 }}>
              ✕ Cancel Edit
            </button>
          )}
        </div>
      </div>

      <div className="card-body">
        {/* Quick Templates — only when not editing */}
        {!isEditing && (
          <div style={{ marginBottom:16 }}>
            <div style={{ fontSize:11, fontFamily:"'Syne',sans-serif", fontWeight:700, letterSpacing:"0.06em", textTransform:"uppercase", color:"var(--text-secondary)", marginBottom:7 }}>Quick Add</div>
            <div style={{ display:"flex", gap:7, flexWrap:"wrap" }}>
              {QUICK_TEMPLATES.map((tpl,i) => (
                <button key={i} type="button" onClick={() => applyTemplate(tpl)}
                  style={{ padding:"6px 12px", borderRadius:20, border:"1px solid var(--border)", background:"var(--bg-input)", color:"var(--text-secondary)", fontSize:12, cursor:"pointer", fontFamily:"'Syne',sans-serif", fontWeight:600, transition:"all 0.15s", whiteSpace:"nowrap" }}
                  onMouseEnter={e => { e.currentTarget.style.borderColor=accent; e.currentTarget.style.color=accent; }}
                  onMouseLeave={e => { e.currentTarget.style.borderColor="var(--border)"; e.currentTarget.style.color="var(--text-secondary)"; }}>
                  {tpl.label}
                </button>
              ))}
            </div>
          </div>
        )}

        {/* Type Pill Tabs */}
        <div style={{ marginBottom:18 }}>
          <div style={{ fontSize:11, fontFamily:"'Syne',sans-serif", fontWeight:700, letterSpacing:"0.06em", textTransform:"uppercase", color:"var(--text-secondary)", marginBottom:7 }}>Transaction Type</div>
          <div style={{ display:"flex", flexWrap:"wrap", gap:7 }}>
            {Object.entries(TYPE_META).map(([t, meta]) => (
              <button key={t} type="button" onClick={() => { setType(t); setCategory(""); }}
                style={{
                  padding:"7px 14px", borderRadius:20, border:`1.5px solid ${meta.accent}`,
                  color: type===t ? meta.accent : "var(--text-muted)",
                  background: type===t ? `${meta.accent}18` : "transparent",
                  fontSize:12, fontWeight:700, fontFamily:"'Syne',sans-serif",
                  cursor:"pointer", transition:"all 0.15s",
                }}>
                {meta.icon} {meta.label}
              </button>
            ))}
          </div>
        </div>

        <form onSubmit={handleSubmit}>
          <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fill,minmax(160px,1fr))", gap:12, alignItems:"start" }}>

            <div>
              <label className="form-label">Description *</label>
              <input type="text" className="form-control" value={description}
                onChange={e => setDescription(e.target.value)} placeholder="What was this for?" />
            </div>

            <div>
              <label className="form-label">Amount (₹) *</label>
              <input type="number" className="form-control" value={amount} min="0" step="0.01"
                onChange={e => setAmount(e.target.value)} placeholder="0.00" />
            </div>

            <div>
              <label className="form-label">Category *</label>
              <select className="form-select" value={category} onChange={e => handleCategoryChange(e.target.value)}>
                <option value="">Select…</option>
                {CATEGORIES[type]?.map((c,i) => <option key={i} value={c}>{c}</option>)}
              </select>
            </div>

            <div>
              <label className="form-label">Bank / Wallet *</label>
              <select className="form-select" value={bank} onChange={e => setBank(e.target.value)}>
                {BANKS.map((b,i) => <option key={i} value={b}>{b}</option>)}
              </select>
            </div>

            <div>
              <label className="form-label">Date *</label>
              <input type="date" className="form-control" value={date} onChange={e => setDate(e.target.value)} />
            </div>

            <div>
              <label className="form-label">Note (optional)</label>
              <input type="text" className="form-control" value={note}
                onChange={e => setNote(e.target.value)} placeholder="Extra note…" />
            </div>
          </div>

          {/* Recurring toggle — only for new non-borrow entries */}
          {!isEditing && (type === "expense" || type === "income" || type === "investment") && (
            <div style={{ display:"flex", alignItems:"center", gap:10, marginTop:14, padding:"10px 14px", borderRadius:10, background:"var(--bg-input)", border:"1px solid var(--border)" }}>
              <label style={{ display:"flex", alignItems:"center", gap:8, cursor:"pointer", userSelect:"none" }}>
                <div onClick={() => setRecurring(r => !r)}
                  style={{ width:40, height:22, borderRadius:11, background: recurring ? accent : "var(--border)", position:"relative", transition:"background 0.2s", cursor:"pointer", flexShrink:0 }}>
                  <div style={{ position:"absolute", top:3, left: recurring ? 20 : 3, width:16, height:16, borderRadius:"50%", background:"#fff", transition:"left 0.2s", boxShadow:"0 1px 4px rgba(0,0,0,0.3)" }} />
                </div>
                <span style={{ fontSize:12.5, fontFamily:"'Syne',sans-serif", fontWeight:600, color:"var(--text-secondary)" }}>
                  🔁 Also add next month (Recurring)
                </span>
              </label>
            </div>
          )}

          <div style={{ display:"flex", gap:10, marginTop:14 }}>
            <button type="submit" className="btn" style={{
              flex:1, background:`linear-gradient(135deg,${accent},${accent}bb)`,
              color:"#fff", boxShadow:`0 4px 14px ${accent}30`,
              border:"none", borderRadius:10, padding:"11px",
            }}>
              {isEditing ? "💾 Save Changes" : "➕ Add Entry"}
            </button>
            {!isEditing && (
              <button type="button" onClick={resetForm} className="btn btn-secondary">
                Reset
              </button>
            )}
          </div>
        </form>
      </div>
    </div>
  );
}