import React from "react";

export default function Filter({ filter, setFilter }) {
  const hasFilter = filter.from || filter.to;

  const presets = [
    { label: "Today",      days: 0  },
    { label: "This Week",  days: 7  },
    { label: "This Month", days: 30 },
    { label: "3 Months",   days: 90 },
  ];

  const applyPreset = (days) => {
    const to   = new Date().toISOString().split("T")[0];
    const from = new Date(Date.now() - days * 86400000).toISOString().split("T")[0];
    setFilter(days === 0 ? { from:to, to } : { from, to });
  };

  return (
    <div className="card mb-3">
      <div className="card-header bg-info">
        <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center" }}>
          <div style={{ display:"flex", alignItems:"center", gap:8 }}>
            <div style={{ width:8, height:8, borderRadius:"50%", background:"var(--accent-teal)", boxShadow:"0 0 8px var(--accent-teal)" }} />
            <h5 style={{ margin:0, color:"var(--accent-teal)" }}>Filter Entries</h5>
          </div>
          {hasFilter && (
            <button onClick={() => setFilter({ from:"", to:"" })}
              style={{ background:"none", border:"1px solid rgba(252,129,129,0.4)", color:"var(--accent-red)", borderRadius:7, padding:"3px 11px", fontSize:12, cursor:"pointer", fontFamily:"'Syne',sans-serif", fontWeight:600 }}>
              Clear ×
            </button>
          )}
        </div>
      </div>
      <div className="card-body">
        {/* Quick presets */}
        <div style={{ display:"flex", gap:7, marginBottom:14, flexWrap:"wrap" }}>
          {presets.map(p => (
            <button key={p.label} type="button" onClick={() => applyPreset(p.days)}
              style={{
                padding:"5px 13px", borderRadius:20, fontSize:12, cursor:"pointer",
                fontFamily:"'Syne',sans-serif", fontWeight:600, border:"1px solid var(--border)",
                background:"var(--bg-input)", color:"var(--text-secondary)",
                transition:"all 0.15s",
              }}
              onMouseEnter={e => { e.currentTarget.style.borderColor="var(--accent-teal)"; e.currentTarget.style.color="var(--accent-teal)"; }}
              onMouseLeave={e => { e.currentTarget.style.borderColor="var(--border)"; e.currentTarget.style.color="var(--text-secondary)"; }}>
              {p.label}
            </button>
          ))}
        </div>

        <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:12 }} className="filter-grid">
          <div>
            <label className="form-label">From</label>
            <input type="date" className="form-control" value={filter.from}
              onChange={e => setFilter({ ...filter, from:e.target.value })} />
          </div>
          <div>
            <label className="form-label">To</label>
            <input type="date" className="form-control" value={filter.to}
              onChange={e => setFilter({ ...filter, to:e.target.value })} />
          </div>
        </div>

        {hasFilter && (
          <div style={{ marginTop:10, padding:"7px 13px", borderRadius:8, background:"rgba(79,209,197,0.09)", border:"1px solid rgba(79,209,197,0.22)", fontSize:12, color:"var(--accent-teal)", fontWeight:600 }}>
            🔍 Filtered: {filter.from || "start"} → {filter.to || "today"}
          </div>
        )}
      </div>
    </div>
  );
}