import React, { useState, useMemo } from "react";

const EXPENSE_CATS = ["Food","Rent","Travel","Utilities","Entertainment","Healthcare","Shopping","Education","Other"];
const MONTHS = Array.from({length:12},(_,i)=>({
  value: String(i+1).padStart(2,"0"),
  label: new Date(2000,i).toLocaleString("default",{month:"long"}),
}));

function ProgressBar({ pct, color }) {
  const clamped = Math.min(pct, 100);
  const barColor = pct >= 100 ? "#fc8181" : pct >= 80 ? "#f6e05e" : color || "#68d391";
  return (
    <div style={{ background:"var(--bg-input)", borderRadius:20, height:8, overflow:"hidden", marginTop:5 }}>
      <div style={{ width:`${clamped}%`, height:"100%", borderRadius:20, background:barColor, transition:"width 0.5s ease", boxShadow:pct>=100?`0 0 8px ${barColor}88`:"none" }} />
    </div>
  );
}

export default function Budget({ entries, budgets, onSave, onDelete }) {
  const now    = new Date();
  const [selYear,  setSelYear]  = useState(now.getFullYear());
  const [selMonth, setSelMonth] = useState(String(now.getMonth()+1).padStart(2,"0"));
  const [editCat,  setEditCat]  = useState(null);
  const [editAmt,  setEditAmt]  = useState("");

  const yearMonth = `${selYear}-${selMonth}`;

  // Build budget map for selected month
  const budgetMap = useMemo(() => {
    const m = {};
    budgets.forEach(b => { if (b.key.startsWith(yearMonth+":")) { const cat=b.key.split(":")[1]; m[cat]=b.amount; } });
    return m;
  }, [budgets, yearMonth]);

  // Calculate actual spending per category for selected month
  const spendMap = useMemo(() => {
    const m = {};
    entries.filter(e => e.type==="expense" && e.date?.startsWith(yearMonth) && e.category!=="Bank Transfer")
      .forEach(e => { m[e.category]=(m[e.category]||0)+e.amount; });
    return m;
  }, [entries, yearMonth]);

  const totalBudgeted = Object.values(budgetMap).reduce((s,v)=>s+v,0);
  const totalSpent    = Object.values(spendMap).reduce((s,v)=>s+v,0);
  const totalPct      = totalBudgeted > 0 ? (totalSpent/totalBudgeted)*100 : 0;

  const years = [now.getFullYear()-1, now.getFullYear(), now.getFullYear()+1];

  const handleSave = (cat) => {
    const amt = parseFloat(editAmt);
    if (!amt || amt <= 0) return;
    onSave(`${yearMonth}:${cat}`, amt);
    setEditCat(null); setEditAmt("");
  };

  const allCats = [...new Set([...EXPENSE_CATS, ...Object.keys(spendMap)])];

  return (
    <div>
      {/* ── Header ── */}
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:18, flexWrap:"wrap", gap:10 }}>
        <div>
          <h2 style={{ margin:0, fontSize:20 }}>🎯 Budget Tracker</h2>
          <p style={{ margin:0, color:"var(--text-secondary)", fontSize:13 }}>Set monthly budgets per category and track spending</p>
        </div>
        {/* Month / Year picker */}
        <div style={{ display:"flex", gap:8 }}>
          <select className="form-select" style={{ width:"auto" }} value={selMonth} onChange={e=>setSelMonth(e.target.value)}>
            {MONTHS.map(m=><option key={m.value} value={m.value}>{m.label}</option>)}
          </select>
          <select className="form-select" style={{ width:"auto" }} value={selYear} onChange={e=>setSelYear(+e.target.value)}>
            {years.map(y=><option key={y} value={y}>{y}</option>)}
          </select>
        </div>
      </div>

      {/* ── Overall summary card ── */}
      <div className="card" style={{ marginBottom:16 }}>
        <div className="card-body" style={{ display:"flex", flexWrap:"wrap", gap:20, alignItems:"center" }}>
          <div style={{ flex:1, minWidth:200 }}>
            <div style={{ fontSize:11, fontFamily:"'Syne',sans-serif", fontWeight:700, letterSpacing:"0.07em", textTransform:"uppercase", color:"var(--text-secondary)", marginBottom:4 }}>
              Monthly Overview — {MONTHS.find(m=>m.value===selMonth)?.label} {selYear}
            </div>
            <div style={{ display:"flex", gap:20, flexWrap:"wrap" }}>
              <div>
                <div style={{ fontSize:11, color:"var(--text-secondary)" }}>Total Budget</div>
                <div style={{ fontSize:20, fontWeight:800, fontFamily:"'Syne',sans-serif", color:"var(--accent-blue)" }}>₹{totalBudgeted.toLocaleString("en-IN")}</div>
              </div>
              <div>
                <div style={{ fontSize:11, color:"var(--text-secondary)" }}>Spent</div>
                <div style={{ fontSize:20, fontWeight:800, fontFamily:"'Syne',sans-serif", color: totalPct>=100?"var(--accent-red)":"var(--accent-green)" }}>₹{totalSpent.toLocaleString("en-IN")}</div>
              </div>
              <div>
                <div style={{ fontSize:11, color:"var(--text-secondary)" }}>Remaining</div>
                <div style={{ fontSize:20, fontWeight:800, fontFamily:"'Syne',sans-serif", color: (totalBudgeted-totalSpent)>=0?"var(--accent-teal)":"var(--accent-red)" }}>
                  ₹{(totalBudgeted-totalSpent).toLocaleString("en-IN")}
                </div>
              </div>
            </div>
            <ProgressBar pct={totalPct} />
            <div style={{ fontSize:11, color:"var(--text-secondary)", marginTop:4 }}>{totalPct.toFixed(1)}% of total budget used</div>
          </div>
        </div>
      </div>

      {/* ── Per-category rows ── */}
      <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fill,minmax(290px,1fr))", gap:12 }}>
        {allCats.map(cat => {
          const budgeted = budgetMap[cat] || 0;
          const spent    = spendMap[cat]  || 0;
          const pct      = budgeted > 0 ? (spent/budgeted)*100 : 0;
          const remaining= budgeted - spent;
          const isEditing= editCat === cat;

          return (
            <div key={cat} className="card" style={{ borderColor: pct>=100 ? "rgba(252,129,129,0.3)" : pct>=80 ? "rgba(246,224,94,0.3)" : undefined }}>
              <div className="card-body" style={{ padding:"14px 16px !important" }}>
                <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:8 }}>
                  <div>
                    <div style={{ fontFamily:"'Syne',sans-serif", fontWeight:700, fontSize:14, color:"var(--text-primary)" }}>{cat}</div>
                    <div style={{ fontSize:11, color:"var(--text-secondary)" }}>
                      Spent: <strong style={{ color:pct>=100?"var(--accent-red)":"var(--text-primary)" }}>₹{spent.toLocaleString("en-IN",{minimumFractionDigits:2})}</strong>
                      {budgeted > 0 && <> / ₹{budgeted.toLocaleString("en-IN")}</>}
                    </div>
                  </div>
                  <div style={{ display:"flex", gap:5, alignItems:"center" }}>
                    {pct>=100 && <span style={{ fontSize:16 }}>🚨</span>}
                    {pct>=80 && pct<100 && <span style={{ fontSize:16 }}>⚠️</span>}
                    <button onClick={() => { setEditCat(cat); setEditAmt(budgeted||""); }}
                      style={{ padding:"4px 10px", borderRadius:7, border:"1px solid var(--border)", background:"var(--bg-input)", color:"var(--text-secondary)", cursor:"pointer", fontSize:11, fontFamily:"'Syne',sans-serif", fontWeight:600 }}>
                      {budgeted ? "Edit" : "Set"}
                    </button>
                    {budgeted > 0 && (
                      <button onClick={() => onDelete(`${yearMonth}:${cat}`)}
                        style={{ padding:"4px 8px", borderRadius:7, border:"1px solid rgba(252,129,129,0.3)", background:"rgba(252,129,129,0.1)", color:"var(--accent-red)", cursor:"pointer", fontSize:11 }}>✕</button>
                    )}
                  </div>
                </div>

                {isEditing ? (
                  <div style={{ display:"flex", gap:7, marginTop:6 }}>
                    <input type="number" autoFocus value={editAmt} onChange={e=>setEditAmt(e.target.value)}
                      onKeyDown={e=>{ if(e.key==="Enter") handleSave(cat); if(e.key==="Escape") setEditCat(null); }}
                      placeholder="Budget amount ₹" className="form-control" style={{ flex:1, fontSize:13 }} />
                    <button onClick={()=>handleSave(cat)} className="btn btn-success btn-sm">Save</button>
                    <button onClick={()=>setEditCat(null)} className="btn btn-secondary btn-sm">✕</button>
                  </div>
                ) : (
                  <>
                    {budgeted > 0
                      ? <>
                          <ProgressBar pct={pct} />
                          <div style={{ display:"flex", justifyContent:"space-between", marginTop:5, fontSize:11 }}>
                            <span style={{ color:"var(--text-secondary)" }}>{pct.toFixed(0)}% used</span>
                            <span style={{ color: remaining>=0?"var(--accent-green)":"var(--accent-red)", fontWeight:700 }}>
                              {remaining>=0?"Remaining":"Over by"}: ₹{Math.abs(remaining).toLocaleString("en-IN")}
                            </span>
                          </div>
                        </>
                      : <div style={{ fontSize:12, color:"var(--text-muted)", marginTop:4 }}>
                          {spent > 0 ? `Spent ₹${spent.toFixed(2)} — no budget set` : "No budget set"}
                        </div>
                    }
                  </>
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}