import React, { useEffect, useState } from "react";

/**
 * SplashScreen.js
 * ─────────────────────────────────────────────
 * Mobile-first splash screen for Shivam Sharma Finance Tracker
 * Shows for ~2.8s then smoothly fades out.
 *
 * Usage (already wired in App.js):
 *   if (splash) return <SplashScreen onDone={() => setSplash(false)} />;
 */
export default function SplashScreen({ onDone }) {
  const [phase, setPhase] = useState("enter"); // enter → hold → exit

  useEffect(() => {
    // enter animation: 0 → 0.6s
    // hold:            0.6s → 2.4s
    // exit fade:       2.4s → 2.9s
    const t1 = setTimeout(() => setPhase("hold"), 800);
    const t2 = setTimeout(() => setPhase("exit"), 2800);
    const t3 = setTimeout(() => onDone?.(), 3000);
    return () => { clearTimeout(t1); clearTimeout(t2); clearTimeout(t3); };
  }, [onDone]);

  const exiting = phase === "exit";

  return (
    <div style={{
      position: "fixed", inset: 0, zIndex: 9999,
      background: "#060810",
      display: "flex", flexDirection: "column",
      alignItems: "center", justifyContent: "center",
      overflow: "hidden",
      // Exit transition
      opacity:    exiting ? 0 : 1,
      transform:  exiting ? "scale(1.04)" : "scale(1)",
      transition: exiting ? "opacity 0.5s ease, transform 0.5s ease" : "none",
    }}>

      {/* ── NOISE TEXTURE ── */}
      <div style={{
        position: "absolute", inset: 0, pointerEvents: "none", zIndex: 0,
        backgroundImage: `url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.05'/%3E%3C/svg%3E")`,
        opacity: 0.5,
      }} />

      {/* ── GRID ── */}
      <div style={{
        position: "absolute", inset: 0, pointerEvents: "none", zIndex: 0,
        backgroundImage: "linear-gradient(rgba(255,255,255,0.03) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,0.03) 1px,transparent 1px)",
        backgroundSize: "50px 50px",
        maskImage: "radial-gradient(ellipse 80% 80% at 50% 50%, black 20%, transparent 100%)",
        WebkitMaskImage: "radial-gradient(ellipse 80% 80% at 50% 50%, black 20%, transparent 100%)",
      }} />

      {/* ── AMBIENT BLOBS ── */}
      <div style={{ position:"absolute", width:400, height:400, borderRadius:"50%", background:"rgba(46,204,113,0.08)", filter:"blur(80px)", top:"-100px", left:"-80px", animation:"blobDrift1 12s ease-in-out infinite alternate", zIndex:0 }} />
      <div style={{ position:"absolute", width:350, height:350, borderRadius:"50%", background:"rgba(243,156,18,0.07)",  filter:"blur(80px)", bottom:"-80px", right:"-60px", animation:"blobDrift2 16s ease-in-out infinite alternate", zIndex:0 }} />
      <div style={{ position:"absolute", width:250, height:250, borderRadius:"50%", background:"rgba(78,205,196,0.06)",  filter:"blur(60px)", top:"50%", left:"50%", transform:"translate(-50%,-50%)", animation:"blobDrift3 10s ease-in-out infinite alternate", zIndex:0 }} />

      {/* ── MAIN CONTENT ── */}
      <div style={{ position:"relative", zIndex:1, display:"flex", flexDirection:"column", alignItems:"center", width:"100%", padding:"0 32px" }}>

        {/* Orbit icon */}
        <div style={{ position:"relative", width:140, height:140, marginBottom:36, animation:"floatUD 5s ease-in-out infinite" }}>

          {/* Ring 1 */}
          <div style={{ position:"absolute", inset:0, borderRadius:"50%", border:"1px solid rgba(46,204,113,0.3)", animation:"spinRing 18s linear infinite" }}>
            <div style={{ position:"absolute", top:-5, left:"50%", transform:"translateX(-50%)", width:10, height:10, borderRadius:"50%", background:"#2ECC71", boxShadow:"0 0 12px #2ECC71" }} />
          </div>

          {/* Ring 2 */}
          <div style={{ position:"absolute", inset:18, borderRadius:"50%", border:"1px solid rgba(243,156,18,0.25)", animation:"spinRing 12s linear infinite reverse" }}>
            <div style={{ position:"absolute", top:-4, left:"50%", transform:"translateX(-50%)", width:8, height:8, borderRadius:"50%", background:"#F39C12", boxShadow:"0 0 10px #F39C12" }} />
          </div>

          {/* Ring 3 */}
          <div style={{ position:"absolute", inset:34, borderRadius:"50%", border:"1px solid rgba(78,205,196,0.2)", animation:"spinRing 8s linear infinite" }}>
            <div style={{ position:"absolute", top:-4, left:"50%", transform:"translateX(-50%)", width:7, height:7, borderRadius:"50%", background:"#4ECDC4", boxShadow:"0 0 8px #4ECDC4" }} />
          </div>

          {/* Core circle */}
          <div style={{
            position:"absolute", inset:48,
            borderRadius:"50%",
            background:"linear-gradient(135deg,rgba(46,204,113,0.15),rgba(243,156,18,0.1))",
            border:"1px solid rgba(255,255,255,0.1)",
            display:"flex", alignItems:"center", justifyContent:"center",
            backdropFilter:"blur(12px)",
            boxShadow:"0 0 40px rgba(46,204,113,0.2), inset 0 0 20px rgba(46,204,113,0.05)",
          }}>
            <span style={{
              fontSize:28, fontWeight:700, lineHeight:1,
              fontFamily:"Georgia,serif",
              background:"linear-gradient(135deg,#2ECC71,#F39C12)",
              WebkitBackgroundClip:"text", WebkitTextFillColor:"transparent",
            }}>₹</span>
          </div>
        </div>

        {/* App label */}
        <div style={{
          fontSize:10, fontFamily:"'Syne',sans-serif", fontWeight:700,
          letterSpacing:"0.2em", textTransform:"uppercase",
          color:"#2ECC71", marginBottom:14,
          animation:"fadeSlideUp 0.7s 0.3s ease both",
        }}>Personal Finance Tracker</div>

        {/* NAME — Shivam */}
        <div style={{
          fontFamily:"Georgia,'Times New Roman',serif",
          fontSize:"clamp(44px,12vw,72px)",
          fontWeight:700, lineHeight:1,
          color:"#E8EDF5", letterSpacing:"-0.02em",
          marginBottom:4,
          animation:"fadeSlideUp 0.8s 0.45s ease both",
        }}>Shivam</div>

        {/* NAME — Sharma (gradient) */}
        <div style={{
          fontFamily:"Georgia,'Times New Roman',serif",
          fontSize:"clamp(44px,12vw,72px)",
          fontWeight:700, lineHeight:1,
          letterSpacing:"-0.02em",
          marginBottom:20,
          background:"linear-gradient(135deg,#2ECC71 0%,#F39C12 50%,#E74C3C 100%)",
          WebkitBackgroundClip:"text", WebkitTextFillColor:"transparent",
          animation:"fadeSlideUp 0.8s 0.6s ease both",
        }}>Sharma</div>

        {/* Tagline */}
        <div style={{
          fontSize:11, letterSpacing:"0.14em", textTransform:"uppercase",
          color:"rgba(232,237,245,0.35)", marginBottom:40,
          animation:"fadeSlideUp 0.8s 0.75s ease both",
          fontFamily:"'Syne',sans-serif", fontWeight:600,
        }}>Smart · Automated · AI-Powered</div>

        {/* Feature pills */}
        <div style={{
          display:"flex", gap:8, flexWrap:"wrap", justifyContent:"center",
          maxWidth:320,
          animation:"fadeSlideUp 0.8s 0.9s ease both",
        }}>
          {[
            { icon:"📊", label:"Dashboard" },
            { icon:"🎯", label:"Budget"    },
            { icon:"🤖", label:"AI Mentor" },
            { icon:"↔️", label:"Transfer"  },
          ].map((f,i) => (
            <div key={i} style={{
              padding:"7px 14px", borderRadius:20,
              background:"rgba(255,255,255,0.04)",
              border:"1px solid rgba(255,255,255,0.08)",
              display:"flex", alignItems:"center", gap:6,
              backdropFilter:"blur(8px)",
              fontSize:12, fontFamily:"'Syne',sans-serif", fontWeight:700,
              color:"rgba(232,237,245,0.7)",
            }}>
              <span style={{ fontSize:13 }}>{f.icon}</span> {f.label}
            </div>
          ))}
        </div>
      </div>

      {/* ── BOTTOM LOADING BAR ── */}
      <div style={{
        position:"absolute", bottom:0, left:0, right:0,
        height:3, background:"rgba(255,255,255,0.05)", zIndex:2,
      }}>
        <div style={{
          height:"100%",
          background:"linear-gradient(90deg,#2ECC71,#F39C12,#E74C3C)",
          borderRadius:2,
          animation:"loadBar 3s ease-out forwards",
        }} />
      </div>

      {/* ── BOTTOM BRAND ── */}
      <div style={{
        position:"absolute", bottom:16, zIndex:2,
        fontSize:11, color:"rgba(255,255,255,0.2)",
        fontFamily:"Georgia,serif", fontStyle:"italic", letterSpacing:"0.05em",
        animation:"fadeSlideUp 0.8s 1s ease both",
      }}>
        Shivam Sharma · Finance Tracker
      </div>

      {/* Animations */}
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Syne:wght@600;700&display=swap');

        @keyframes spinRing     { from{transform:rotate(0deg)} to{transform:rotate(360deg)} }
        @keyframes floatUD      { 0%,100%{transform:translateY(0)} 50%{transform:translateY(-10px)} }
        @keyframes fadeSlideUp  { from{opacity:0;transform:translateY(16px)} to{opacity:1;transform:translateY(0)} }
        @keyframes loadBar      { from{width:0%} to{width:100%} }
        @keyframes blobDrift1   { from{transform:translate(0,0)}         to{transform:translate(40px,30px)}    }
        @keyframes blobDrift2   { from{transform:translate(0,0)}         to{transform:translate(-30px,-40px)}  }
        @keyframes blobDrift3   { from{transform:translate(-50%,-50%) scale(1)} to{transform:translate(-50%,-50%) scale(1.2)} }
      `}</style>
    </div>
  );
}