import React, { useState, useMemo } from "react";
import { BsTrash, BsPencil, BsDownload, BsSearch } from "react-icons/bs";
import Swal from "sweetalert2";

const TYPE_COLOR = { income:"#68d391", expense:"#fc8181", investment:"#63b3ed", borrow:"#b794f4", borrowReturn:"#f6e05e" };
const TYPE_BG    = { income:"rgba(104,211,145,0.12)", expense:"rgba(252,129,129,0.12)", investment:"rgba(99,179,237,0.12)", borrow:"rgba(183,148,244,0.12)", borrowReturn:"rgba(246,224,94,0.12)" };
const TYPE_LABEL = { income:"Income", expense:"Expense", investment:"Investment", borrow:"Borrow", borrowReturn:"Borrow Return" };

function Badge({ type }) {
  return (
    <span style={{ display:"inline-block", padding:"3px 10px", borderRadius:20, fontSize:10.5, fontWeight:700, fontFamily:"'Syne',sans-serif", letterSpacing:"0.04em", background:TYPE_BG[type]||"rgba(255,255,255,0.08)", color:TYPE_COLOR[type]||"var(--text-primary)", border:`1px solid ${(TYPE_COLOR[type]||"#fff")}35` }}>
      {TYPE_LABEL[type] || type}
    </span>
  );
}

// Export entries to CSV
function exportCSV(entries) {
  const header = ["Date","Type","Description","Category","Bank","Amount","Note"];
  const rows   = entries.map(e => [e.date, e.type, `"${e.description}"`, e.category, e.bank, e.amount, `"${e.note||""}"`]);
  const csv    = [header, ...rows].map(r => r.join(",")).join("\n");
  const blob   = new Blob([csv], { type:"text/csv" });
  const url    = URL.createObjectURL(blob);
  const a      = document.createElement("a");
  a.href=url; a.download=`finance_export_${new Date().toISOString().split("T")[0]}.csv`;
  a.click(); URL.revokeObjectURL(url);
}

export default function EntriesList({ entries, deleteEntry, bulkDelete, onEdit }) {
  const [sort,       setSort]       = useState({ key:"date", dir:"desc" });
  const [filterType, setFilterType] = useState("");
  const [filterBank, setFilterBank] = useState("");
  const [search,     setSearch]     = useState("");
  const [page,       setPage]       = useState(1);
  const [selected,   setSelected]   = useState(new Set());
  const PER_PAGE = 10;

  const sorted = useMemo(() => [...entries]
    .filter(e => filterType ? e.type === filterType : true)
    .filter(e => filterBank ? e.bank === filterBank : true)
    .filter(e => {
      if (!search.trim()) return true;
      const q = search.toLowerCase();
      return (e.description||"").toLowerCase().includes(q)
          || (e.category||"").toLowerCase().includes(q)
          || (e.bank||"").toLowerCase().includes(q)
          || String(e.amount).includes(q);
    })
    .sort((a,b) => {
      let A = a[sort.key], B = b[sort.key];
      if (sort.key==="amount") { A=+A; B=+B; }
      else if (sort.key==="date") { A=new Date(A); B=new Date(B); }
      else { A=A?.toString().toLowerCase()||""; B=B?.toString().toLowerCase()||""; }
      return A<B ? (sort.dir==="asc"?-1:1) : A>B ? (sort.dir==="asc"?1:-1) : 0;
    }), [entries, filterType, filterBank, search, sort]);

  const totalPages = Math.ceil(sorted.length / PER_PAGE) || 1;
  const paged      = sorted.slice((page-1)*PER_PAGE, page*PER_PAGE);
  const total      = sorted.reduce((s,e) => s + e.amount, 0);

  const requestSort = key => {
    setSort(prev => ({ key, dir: prev.key===key && prev.dir==="asc" ? "desc" : "asc" }));
    setPage(1);
  };
  const SortArrow = ({ k }) => sort.key===k
    ? <span style={{ color:"var(--accent-blue)", marginLeft:3, fontSize:11 }}>{sort.dir==="asc"?"↑":"↓"}</span>
    : <span style={{ color:"var(--text-muted)", marginLeft:3, fontSize:10 }}>↕</span>;

  const uniqueTypes = [...new Set(entries.map(e => e.type))];
  const uniqueBanks = [...new Set(entries.map(e => e.bank).filter(Boolean))];

  // Selection
  const toggleSelect  = id => setSelected(prev => { const s=new Set(prev); s.has(id)?s.delete(id):s.add(id); return s; });
  const toggleAll     = () => setSelected(selected.size===paged.length ? new Set() : new Set(paged.map(e=>e.id)));
  const allSelected   = paged.length > 0 && selected.size === paged.length;

  const doDelete = id => {
    Swal.fire({ title:"Delete entry?", text:"Cannot be undone.", icon:"warning",
      showCancelButton:true, confirmButtonColor:"#e53e3e", cancelButtonColor:"#4a5568",
      confirmButtonText:"Delete", background:"var(--bg-surface)", color:"var(--text-primary)" })
    .then(r => { if (r.isConfirmed) deleteEntry(id); });
  };

  const doBulkDelete = () => {
    if (selected.size === 0) return;
    Swal.fire({ title:`Delete ${selected.size} entries?`, text:"Cannot be undone.", icon:"warning",
      showCancelButton:true, confirmButtonColor:"#e53e3e", confirmButtonText:"Delete All",
      background:"var(--bg-surface)", color:"var(--text-primary)" })
    .then(r => { if (r.isConfirmed) { bulkDelete([...selected]); setSelected(new Set()); }});
  };

  // Income/expense breakdown of filtered
  const incomeTotal  = sorted.filter(e=>e.type==="income").reduce((s,e)=>s+e.amount,0);
  const expenseTotal = sorted.filter(e=>e.type==="expense").reduce((s,e)=>s+e.amount,0);

  return (
    <div className="card">
      <div className="card-body">

        {/* ── Toolbar ── */}
        <div style={{ display:"flex", flexWrap:"wrap", gap:10, marginBottom:14, alignItems:"center" }}>
          <div style={{ display:"flex", alignItems:"center", gap:8, flex:1, minWidth:180, background:"var(--bg-input)", borderRadius:10, padding:"7px 12px", border:"1px solid var(--border)" }}>
            <BsSearch size={13} style={{ color:"var(--text-muted)" }} />
            <input value={search} onChange={e=>{setSearch(e.target.value);setPage(1);}}
              placeholder="Search entries…" style={{ border:"none", background:"transparent", outline:"none", color:"var(--text-primary)", fontSize:13, width:"100%" }} />
            {search && <button onClick={()=>setSearch("")} style={{ background:"none",border:"none",color:"var(--text-muted)",cursor:"pointer",fontSize:14,padding:0 }}>×</button>}
          </div>

          <select className="form-select" style={{ width:"auto",minWidth:120 }} value={filterType}
            onChange={e=>{setFilterType(e.target.value);setPage(1);}}>
            <option value="">All Types</option>
            {uniqueTypes.map((t,i)=><option key={i} value={t}>{TYPE_LABEL[t]||t}</option>)}
          </select>

          <select className="form-select" style={{ width:"auto",minWidth:100 }} value={filterBank}
            onChange={e=>{setFilterBank(e.target.value);setPage(1);}}>
            <option value="">All Banks</option>
            {uniqueBanks.map((b,i)=><option key={i} value={b}>{b}</option>)}
          </select>

          <button onClick={()=>exportCSV(sorted)} title="Export CSV"
            style={{ padding:"8px 13px", borderRadius:9, border:"1px solid var(--border)", background:"var(--bg-input)", color:"var(--text-secondary)", cursor:"pointer", display:"flex", alignItems:"center", gap:6, fontSize:12, fontFamily:"'Syne',sans-serif", fontWeight:600, flexShrink:0 }}>
            <BsDownload size={13}/> Export
          </button>

          {selected.size > 0 && (
            <button onClick={doBulkDelete}
              style={{ padding:"8px 13px", borderRadius:9, border:"1px solid rgba(252,129,129,0.3)", background:"rgba(252,129,129,0.1)", color:"var(--accent-red)", cursor:"pointer", display:"flex", alignItems:"center", gap:6, fontSize:12, fontFamily:"'Syne',sans-serif", fontWeight:600 }}>
              <BsTrash size={13}/> Delete ({selected.size})
            </button>
          )}
        </div>

        {/* ── Quick stats row ── */}
        <div style={{ display:"flex", gap:10, marginBottom:14, flexWrap:"wrap" }}>
          {[
            { label:"Entries", val:sorted.length, color:"var(--accent-blue)" },
            { label:"Income",  val:`₹${incomeTotal.toLocaleString("en-IN",{minimumFractionDigits:2})}`,  color:"var(--accent-green)" },
            { label:"Expense", val:`₹${expenseTotal.toLocaleString("en-IN",{minimumFractionDigits:2})}`, color:"var(--accent-red)" },
            { label:"Net",     val:`₹${(incomeTotal-expenseTotal).toLocaleString("en-IN",{minimumFractionDigits:2})}`,
              color: (incomeTotal-expenseTotal) >= 0 ? "var(--accent-green)" : "var(--accent-red)" },
          ].map(s => (
            <div key={s.label} style={{ padding:"7px 14px", borderRadius:9, background:"var(--bg-input)", border:"1px solid var(--border)", fontSize:12 }}>
              <span style={{ color:"var(--text-secondary)", marginRight:6 }}>{s.label}</span>
              <strong style={{ color:s.color, fontFamily:"'Syne',sans-serif" }}>{s.val}</strong>
            </div>
          ))}
        </div>

        {/* ── Mobile Cards ── */}
        <div className="entries-mobile" style={{ display:"none" }}>
          {paged.length===0
            ? <div style={{ textAlign:"center",padding:"40px 0",color:"var(--text-muted)" }}>📭 No entries</div>
            : paged.map(entry => (
              <div key={entry.id} style={{ background:"var(--bg-input)", borderRadius:12, padding:"12px 14px", marginBottom:8, border:"1px solid var(--border)", display:"flex", justifyContent:"space-between", alignItems:"flex-start" }}>
                <div style={{ flex:1, minWidth:0 }}>
                  <div style={{ display:"flex", alignItems:"center", gap:6, marginBottom:4, flexWrap:"wrap" }}>
                    <Badge type={entry.type} />
                    <span style={{ fontSize:11,color:"var(--text-muted)" }}>{entry.date}</span>
                    <span style={{ fontSize:11,background:"rgba(255,255,255,0.06)",borderRadius:5,padding:"1px 7px",color:"var(--text-secondary)" }}>{entry.bank}</span>
                  </div>
                  <div style={{ fontSize:13,color:"var(--text-primary)",fontWeight:500,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis" }}>{entry.description}</div>
                  <div style={{ fontSize:11,color:"var(--text-secondary)",marginTop:2 }}>{entry.category}{entry.note ? ` · ${entry.note}` : ""}</div>
                </div>
                <div style={{ display:"flex",flexDirection:"column",alignItems:"flex-end",gap:6,marginLeft:10 }}>
                  <span style={{ fontWeight:800,fontSize:15,color:TYPE_COLOR[entry.type]||"var(--text-primary)" }}>₹{entry.amount.toFixed(2)}</span>
                  <div style={{ display:"flex",gap:5 }}>
                    <button className="btn btn-sm" onClick={()=>onEdit(entry)} style={{ padding:"4px 7px",background:"rgba(99,179,237,0.15)",border:"1px solid rgba(99,179,237,0.3)",color:"var(--accent-blue)" }}><BsPencil size={11}/></button>
                    <button className="btn btn-sm btn-danger" style={{ padding:"4px 7px" }} onClick={()=>doDelete(entry.id)}><BsTrash size={11}/></button>
                  </div>
                </div>
              </div>
            ))
          }
        </div>

        {/* ── Desktop Table ── */}
        <div className="entries-table" style={{ overflowX:"auto" }}>
          {paged.length===0
            ? <div style={{ textAlign:"center",padding:"48px 0",color:"var(--text-muted)" }}><div style={{ fontSize:36,marginBottom:8 }}>📭</div>No entries found</div>
            : <table className="table table-hover" style={{ whiteSpace:"nowrap",minWidth:600 }}>
                <thead className="table-dark">
                  <tr>
                    <th style={{ width:38 }}>
                      <input type="checkbox" checked={allSelected} onChange={toggleAll}
                        style={{ accentColor:"var(--accent-blue)", width:14, height:14, cursor:"pointer" }} />
                    </th>
                    {[["date","Date"],["type","Type"],["description","Description"],["category","Category"],["bank","Bank"],["amount","Amount"]].map(([k,l])=>(
                      <th key={k} onClick={()=>requestSort(k)} style={{ cursor:"pointer",userSelect:"none" }}>{l}<SortArrow k={k}/></th>
                    ))}
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {paged.map(entry => (
                    <tr key={entry.id} style={{ opacity: selected.has(entry.id) ? 0.75 : 1, background: selected.has(entry.id) ? "rgba(99,179,237,0.06)" : undefined }}>
                      <td>
                        <input type="checkbox" checked={selected.has(entry.id)} onChange={()=>toggleSelect(entry.id)}
                          style={{ accentColor:"var(--accent-blue)", width:14, height:14, cursor:"pointer" }} />
                      </td>
                      <td style={{ color:"var(--text-secondary)",fontSize:12 }}>{entry.date}</td>
                      <td><Badge type={entry.type}/></td>
                      <td style={{ maxWidth:160,overflow:"hidden",textOverflow:"ellipsis" }}>
                        {entry.description}
                        {entry.note && <span style={{ fontSize:10,color:"var(--text-muted)",marginLeft:6 }}>· {entry.note}</span>}
                      </td>
                      <td style={{ color:"var(--text-secondary)" }}>{entry.category}</td>
                      <td><span style={{ background:"rgba(255,255,255,0.06)",borderRadius:5,padding:"2px 8px",fontSize:12 }}>{entry.bank||"-"}</span></td>
                      <td style={{ fontWeight:700,color:TYPE_COLOR[entry.type]||"var(--text-primary)" }}>₹{entry.amount.toFixed(2)}</td>
                      <td>
                        <div style={{ display:"flex",gap:5 }}>
                          <button className="btn btn-sm" onClick={()=>onEdit(entry)}
                            style={{ padding:"4px 8px",background:"rgba(99,179,237,0.14)",border:"1px solid rgba(99,179,237,0.3)",color:"var(--accent-blue)",borderRadius:7 }}>
                            <BsPencil size={12}/>
                          </button>
                          <button className="btn btn-sm btn-danger" style={{ padding:"4px 8px" }} onClick={()=>doDelete(entry.id)}>
                            <BsTrash size={12}/>
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                  <tr style={{ borderTop:"2px solid var(--border)" }}>
                    <td colSpan="6" style={{ textAlign:"right",fontFamily:"'Syne',sans-serif",fontWeight:700,fontSize:11,letterSpacing:"0.06em",textTransform:"uppercase",color:"var(--text-secondary)" }}>
                      Total ({sorted.length} entries)
                    </td>
                    <td style={{ fontWeight:800,fontSize:15,color:"var(--text-primary)" }}>₹{total.toFixed(2)}</td>
                    <td/>
                  </tr>
                </tbody>
              </table>
          }
        </div>

        {/* ── Pagination ── */}
        <div style={{ display:"flex",justifyContent:"space-between",alignItems:"center",marginTop:14,flexWrap:"wrap",gap:8 }}>
          <span style={{ color:"var(--text-secondary)",fontSize:12 }}>Page {page} of {totalPages} · {sorted.length} entries</span>
          <div style={{ display:"flex",gap:5 }}>
            <button className="btn btn-sm btn-outline-primary" disabled={page===1} onClick={()=>setPage(1)}>«</button>
            <button className="btn btn-sm btn-outline-primary" disabled={page===1} onClick={()=>setPage(p=>p-1)}>‹ Prev</button>
            {Array.from({length:Math.min(5,totalPages)},(_,i)=>{
              const p = page<=3 ? i+1 : page+i-2;
              if (p<1||p>totalPages) return null;
              return <button key={p} onClick={()=>setPage(p)}
                style={{ minWidth:30,padding:"5px 8px",borderRadius:7,border:"1px solid var(--border)",cursor:"pointer",fontFamily:"'Syne',sans-serif",fontWeight:700,fontSize:12,
                  background:p===page?"var(--accent-blue)":"var(--bg-input)",
                  color:p===page?"#fff":"var(--text-secondary)" }}>{p}</button>;
            })}
            <button className="btn btn-sm btn-outline-primary" disabled={page===totalPages} onClick={()=>setPage(p=>p+1)}>Next ›</button>
            <button className="btn btn-sm btn-outline-primary" disabled={page===totalPages} onClick={()=>setPage(totalPages)}>»</button>
          </div>
        </div>
      </div>

      <style>{`
        @media (max-width: 600px) { .entries-mobile{display:block!important} .entries-table{display:none} }
      `}</style>
    </div>
  );
}