import React, { useState } from "react";
import Swal from "sweetalert2";

const BANKS = ["BOB", "ICICI", "CASH"];

export default function BankTransferForm({ addTransfer }) {
  const [fromBank, setFromBank] = useState(BANKS[0]);
  const [toBank,   setToBank]   = useState(BANKS[1]);
  const [amount,   setAmount]   = useState("");
  const [date,     setDate]     = useState(new Date().toISOString().split("T")[0]);

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!amount || fromBank === toBank) {
      return Swal.fire({ icon:"error", title:"Invalid", text:"Select different banks and enter amount",
        background:"var(--bg-surface)", color:"var(--text-primary)" });
    }
    addTransfer({ id: Date.now(), type:"transfer", fromBank, toBank, amount: parseFloat(amount), date });
    Swal.fire({ icon:"success", title:"Transfer Done!", timer:1600, showConfirmButton:false,
      background:"var(--bg-surface)", color:"var(--text-primary)" });
    setAmount("");
  };

  return (
    <div className="card">
      <div className="card-header bg-primary">
        <div style={{ display:"flex", alignItems:"center", gap:8 }}>
          <div style={{ width:8, height:8, borderRadius:"50%", background:"var(--accent-blue)", boxShadow:"0 0 8px var(--accent-blue)" }} />
          <h5 style={{ margin:0, color:"var(--accent-blue)" }}>Bank to Bank Transfer</h5>
        </div>
      </div>
      <div className="card-body">
        <form onSubmit={handleSubmit}>
          <div style={{ display:"grid", gridTemplateColumns:"1fr auto 1fr 1fr 1fr", gap:12, alignItems:"end" }}
               className="transfer-grid">

            <div>
              <label className="form-label">From Bank</label>
              <select className="form-select" value={fromBank} onChange={e => setFromBank(e.target.value)}>
                {BANKS.map((b,i) => <option key={i} value={b}>{b}</option>)}
              </select>
            </div>

            <div style={{ display:"flex", alignItems:"center", paddingBottom:2 }}>
              <div style={{
                width:34, height:34, borderRadius:"50%",
                background:"rgba(99,179,237,0.14)", border:"1px solid rgba(99,179,237,0.3)",
                display:"flex", alignItems:"center", justifyContent:"center",
                fontSize:16, color:"var(--accent-blue)",
              }}>→</div>
            </div>

            <div>
              <label className="form-label">To Bank</label>
              <select className="form-select" value={toBank} onChange={e => setToBank(e.target.value)}>
                {BANKS.map((b,i) => <option key={i} value={b}>{b}</option>)}
              </select>
            </div>

            <div>
              <label className="form-label">Amount (₹)</label>
              <input type="number" className="form-control" value={amount} min="0" step="0.01"
                onChange={e => setAmount(e.target.value)} placeholder="0.00" />
            </div>

            <div>
              <label className="form-label">Date</label>
              <input type="date" className="form-control" value={date} onChange={e => setDate(e.target.value)} />
            </div>
          </div>

          <div style={{ marginTop:14 }}>
            <button type="submit" className="btn btn-primary" style={{ width:"100%" }}>
              ↔️ Transfer Funds
            </button>
          </div>
        </form>
      </div>

      <style>{`
        @media (max-width: 600px) {
          .transfer-grid { grid-template-columns: 1fr 1fr !important; }
          .transfer-grid > :nth-child(2) { display: none; }
        }
      `}</style>
    </div>
  );
}