import React, { useMemo } from "react";

const STATS = [
  { key:"balance",    label:"Balance",         icon:"🏦", accent:"#63b3ed" },
  { key:"income",     label:"Income",           icon:"📈", accent:"#68d391" },
  { key:"expense",    label:"Expense",          icon:"📉", accent:"#fc8181" },
  { key:"investment", label:"Investment",       icon:"💼", accent:"#b794f4" },
  { key:"cash",       label:"Cash on Hand",     icon:"💵", accent:"#f6e05e" },
  { key:"borrow",     label:"Outstanding Borrow",icon:"🤝",accent:"#f6ad55" },
];

// Month-over-month change
function MoMBadge({ current, previous }) {
  if (!previous) return null;
  const diff = ((current - previous) / Math.abs(previous)) * 100;
  const up   = diff >= 0;
  return (
    <span style={{ fontSize:10.5, fontWeight:700, marginLeft:6, padding:"2px 6px", borderRadius:10,
      background: up ? "rgba(104,211,145,0.15)" : "rgba(252,129,129,0.15)",
      color: up ? "#68d391" : "#fc8181" }}>
      {up ? "▲" : "▼"} {Math.abs(diff).toFixed(1)}%
    </span>
  );
}

export default function Summary({ entries, onTabChange }) {
  const fmt = n => `₹${Math.abs(n).toLocaleString("en-IN",{minimumFractionDigits:2})}`;
  const now  = new Date();
  const curMY  = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,"0")}`;
  const prevDate = new Date(now.getFullYear(), now.getMonth()-1, 1);
  const prevMY = `${prevDate.getFullYear()}-${String(prevDate.getMonth()+1).padStart(2,"0")}`;

  const calc = useMemo(() => {
    const filtered = entries.filter(e => e.category !== "Bank Transfer");

    const income     = filtered.filter(e=>e.type==="income").reduce((s,e)=>s+e.amount,0);
    const expense    = filtered.filter(e=>e.type==="expense").reduce((s,e)=>s+e.amount,0);
    const investment = filtered.filter(e=>e.type==="investment").reduce((s,e)=>s+e.amount,0);
    const balance    = income - expense - investment;

    const cashIn  = entries.filter(e=>e.bank==="CASH"&&e.type==="income").reduce((s,e)=>s+(e.amount||0),0);
    const cashOut = entries.filter(e=>e.bank==="CASH"&&e.type==="expense").reduce((s,e)=>s+(e.amount||0),0);
    const cash    = cashIn - cashOut;

    const borrow  = entries.filter(e=>e.type==="borrow").reduce((s,e)=>s+(e.amount||0),0)
                  - entries.filter(e=>e.type==="borrowReturn").reduce((s,e)=>s+(e.amount||0),0);

    // Current month
    const curIncome  = filtered.filter(e=>e.type==="income" &&e.date?.startsWith(curMY)).reduce((s,e)=>s+e.amount,0);
    const curExpense = filtered.filter(e=>e.type==="expense"&&e.date?.startsWith(curMY)).reduce((s,e)=>s+e.amount,0);

    // Previous month
    const prevIncome  = filtered.filter(e=>e.type==="income" &&e.date?.startsWith(prevMY)).reduce((s,e)=>s+e.amount,0);
    const prevExpense = filtered.filter(e=>e.type==="expense"&&e.date?.startsWith(prevMY)).reduce((s,e)=>s+e.amount,0);

    return { income, expense, investment, balance, cash, borrow, curIncome, curExpense, prevIncome, prevExpense };
  }, [entries, curMY, prevMY]);

  const vals = { balance:calc.balance, income:calc.income, expense:calc.expense, investment:calc.investment, cash:calc.cash, borrow:calc.borrow };

  // Savings rate this month
  const savingsRate = calc.curIncome > 0
    ? (((calc.curIncome - calc.curExpense) / calc.curIncome) * 100).toFixed(1)
    : null;

  return (
    <div style={{ marginBottom:20 }}>
      {/* Stat cards */}
      <div style={{ display:"grid", gridTemplateColumns:"repeat(3,1fr)", gap:10, marginBottom:10 }} className="summary-grid">
        {STATS.map(s => {
          const val  = vals[s.key];
          const isNeg = val < 0;
          return (
            <div key={s.key} className="stat-card card"
              onClick={() => s.key==="expense" && onTabChange?.("list")}
              style={{ cursor: s.key==="expense" ? "pointer" : "default", borderColor:`${s.accent}25` }}>
              <div className="stat-card-glow" style={{ background:s.accent }} />
              <div style={{ position:"relative" }}>
                <div style={{ width:34,height:34,borderRadius:9,background:`${s.accent}18`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:16,marginBottom:8 }}>{s.icon}</div>
                <div className="stat-label">{s.label}</div>
                <div className="stat-value" style={{ color: isNeg?"var(--accent-red)":s.accent }}>
                  {isNeg?"-":""}{fmt(val)}
                  {s.key==="income"  && <MoMBadge current={calc.curIncome}  previous={calc.prevIncome}  />}
                  {s.key==="expense" && <MoMBadge current={calc.curExpense} previous={calc.prevExpense} />}
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {/* Savings rate banner */}
      {savingsRate !== null && (
        <div style={{
          padding:"10px 16px", borderRadius:10, fontSize:13, fontFamily:"'Syne',sans-serif", fontWeight:600,
          background: parseFloat(savingsRate)>=20 ? "rgba(104,211,145,0.09)" : parseFloat(savingsRate)>=0 ? "rgba(246,224,94,0.09)" : "rgba(252,129,129,0.09)",
          border:`1px solid ${parseFloat(savingsRate)>=20?"rgba(104,211,145,0.25)":parseFloat(savingsRate)>=0?"rgba(246,224,94,0.25)":"rgba(252,129,129,0.25)"}`,
          color: parseFloat(savingsRate)>=20?"var(--accent-green)":parseFloat(savingsRate)>=0?"var(--accent-yellow)":"var(--accent-red)",
          display:"flex", alignItems:"center", gap:8,
        }}>
          {parseFloat(savingsRate)>=20?"💚":parseFloat(savingsRate)>=0?"💛":"❤️"}
          This month's savings rate: <strong>{savingsRate}%</strong>
          <span style={{ fontWeight:400, color:"var(--text-secondary)", fontSize:12 }}>
            {parseFloat(savingsRate)>=20?" · Great job!" : parseFloat(savingsRate)>=0?" · Try to save more" : " · Spending exceeds income!"}
          </span>
        </div>
      )}

      <style>{`
        @media (max-width: 576px) { .summary-grid{grid-template-columns:repeat(2,1fr)!important;gap:8px!important} .stat-value{font-size:13px!important} }
        @media (min-width: 992px) { .summary-grid{grid-template-columns:repeat(6,1fr)!important} }
      `}</style>
    </div>
  );
}