import React, { useState, useEffect, useMemo } from "react";
import {
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend,
  ResponsiveContainer, LineChart, Line, PieChart, Pie, Cell,
  RadarChart, Radar, PolarGrid, PolarAngleAxis, PolarRadiusAxis,
  AreaChart, Area,
} from "recharts";

const COLORS_PIE = ["#68d391","#fc8181","#63b3ed","#b794f4","#f6ad55","#4fd1c5","#f6e05e","#a78bfa"];

const Tip = ({ active, payload, label }) => {
  if (!active||!payload?.length) return null;
  return (
    <div style={{ background:"var(--bg-surface)",border:"1px solid var(--border)",borderRadius:10,padding:"10px 14px",fontSize:12 }}>
      <p style={{ fontFamily:"'Syne',sans-serif",fontWeight:700,color:"var(--text-primary)",marginBottom:6 }}>{label}</p>
      {payload.map((p,i)=>(
        <div key={i} style={{ color:p.color,marginBottom:2 }}>
          {p.name}: <strong>₹{(p.value||0).toLocaleString("en-IN",{minimumFractionDigits:2})}</strong>
        </div>
      ))}
    </div>
  );
};

// Smart insights generator
function generateInsights(entries, monthData, bankData) {
  const insights = [];
  if (!entries.length) return insights;

  const now    = new Date();
  const curMY  = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,"0")}`;
  const prevDate = new Date(now.getFullYear(), now.getMonth()-1, 1);
  const prevMY = `${prevDate.getFullYear()}-${String(prevDate.getMonth()+1).padStart(2,"0")}`;

  const curExp  = entries.filter(e=>e.type==="expense"&&e.date?.startsWith(curMY)&&e.category!=="Bank Transfer").reduce((s,e)=>s+e.amount,0);
  const prevExp = entries.filter(e=>e.type==="expense"&&e.date?.startsWith(prevMY)&&e.category!=="Bank Transfer").reduce((s,e)=>s+e.amount,0);
  const curInc  = entries.filter(e=>e.type==="income" &&e.date?.startsWith(curMY)&&e.category!=="Bank Transfer").reduce((s,e)=>s+e.amount,0);

  if (prevExp>0 && curExp>prevExp*1.2)
    insights.push({ icon:"📈", type:"warning", text:`Expenses up ${(((curExp-prevExp)/prevExp)*100).toFixed(0)}% vs last month (₹${curExp.toFixed(0)} vs ₹${prevExp.toFixed(0)})` });

  if (curInc>0 && curExp>curInc)
    insights.push({ icon:"🚨", type:"danger",  text:`Spending ₹${(curExp-curInc).toFixed(0)} MORE than income this month!` });

  // Top expense category
  const catMap = {};
  entries.filter(e=>e.type==="expense"&&e.date?.startsWith(curMY)&&e.category!=="Bank Transfer")
    .forEach(e=>{catMap[e.category]=(catMap[e.category]||0)+e.amount;});
  const topCat = Object.entries(catMap).sort((a,b)=>b[1]-a[1])[0];
  if (topCat && curExp>0)
    insights.push({ icon:"💸", type:"info", text:`Top spend: ${topCat[0]} (₹${topCat[1].toFixed(0)}, ${((topCat[1]/curExp)*100).toFixed(0)}% of expenses)` });

  // Investment reminder
  const curInvest = entries.filter(e=>e.type==="investment"&&e.date?.startsWith(curMY)).reduce((s,e)=>s+e.amount,0);
  if (curInc>0 && curInvest/curInc < 0.1 && curInc>5000)
    insights.push({ icon:"💼", type:"info", text:`You've invested ${((curInvest/curInc)*100).toFixed(0)}% of income. Aim for 20%+!` });

  // Outstanding borrow
  const netBorrow = entries.filter(e=>e.type==="borrow").reduce((s,e)=>s+e.amount,0)
                  - entries.filter(e=>e.type==="borrowReturn").reduce((s,e)=>s+e.amount,0);
  if (netBorrow > 0)
    insights.push({ icon:"🤝", type:"warning", text:`Outstanding amount to collect: ₹${netBorrow.toFixed(0)}` });

  return insights;
}

export default function Dashboard({ entries, theme }) {
  const [monthData,    setMonthData]    = useState([]);
  const [bankData,     setBankData]     = useState([]);
  const [totalBalance, setTotalBalance] = useState(0);
  const [catExpense,   setCatExpense]   = useState([]);
  const [netWorthData, setNetWorthData] = useState([]);
  const [dayData,      setDayData]      = useState([]);  // last 30 days

  useEffect(() => {
    // Month-wise
    const real = entries.filter(e=>e.category!=="Bank Transfer"||e.bank==="CASH");
    const mg   = {};
    real.forEach(e => {
      const m = new Date(e.date).toLocaleString("default",{month:"short",year:"numeric"});
      if (!mg[m]) mg[m]={name:m,income:0,expense:0,investment:0,borrow:0};
      if (e.type==="borrow") mg[m].borrow+=e.amount;
      else if (mg[m][e.type]!==undefined) mg[m][e.type]+=e.amount;
    });
    const sorted = Object.values(mg).sort((a,b)=>new Date("1 "+a.name)-new Date("1 "+b.name));
    setMonthData(sorted);

    // Net worth cumulative
    let run=0;
    setNetWorthData(sorted.map(m=>{
      run+=(m.income||0)-(m.expense||0)-(m.investment||0);
      return {name:m.name,netWorth:parseFloat(run.toFixed(2))};
    }));

    // Bank-wise
    const bg={};
    entries.forEach(e=>{
      const b=e.bank||"Unknown";
      if(!bg[b]) bg[b]={name:b,income:0,expense:0,investment:0,borrow:0,borrowReturn:0};
      if(e.type==="borrow") bg[b].borrow+=e.amount;
      else if(bg[b][e.type]!==undefined) bg[b][e.type]+=e.amount;
    });
    const banks=Object.values(bg).map(bk=>({...bk,balance:(bk.income+(bk.borrowReturn||0))-(bk.expense+bk.investment+bk.borrow)}));
    setBankData(banks);
    setTotalBalance(banks.reduce((s,b)=>s+b.balance,0));

    // Category pie
    const cg={};
    entries.filter(e=>e.type==="expense"&&e.category!=="Bank Transfer").forEach(e=>{cg[e.category]=(cg[e.category]||0)+e.amount;});
    setCatExpense(Object.entries(cg).map(([name,value])=>({name,value:parseFloat(value.toFixed(2))})).sort((a,b)=>b.value-a.value));

    // Last 30 days daily expense
    const thirtyAgo = new Date(Date.now()-30*86400000);
    const dg={};
    entries.filter(e=>e.type==="expense"&&e.category!=="Bank Transfer"&&new Date(e.date)>=thirtyAgo)
      .forEach(e=>{dg[e.date]=(dg[e.date]||0)+e.amount;});
    setDayData(Object.entries(dg).sort((a,b)=>a[0].localeCompare(b[0])).map(([date,expense])=>({date:date.slice(5),expense})));

  }, [entries]);

  const insights = useMemo(()=>generateInsights(entries,monthData,bankData),[entries,monthData,bankData]);
  const fmt = n => `₹${(n||0).toLocaleString("en-IN",{minimumFractionDigits:2})}`;
  const H = 250;

  const insightColors = { danger:"rgba(252,129,129,0.12)", warning:"rgba(246,224,94,0.10)", info:"rgba(99,179,237,0.10)" };
  const insightBorders= { danger:"rgba(252,129,129,0.3)",  warning:"rgba(246,224,94,0.3)",  info:"rgba(99,179,237,0.3)"  };
  const insightText   = { danger:"var(--accent-red)",      warning:"var(--accent-yellow)",  info:"var(--accent-blue)"    };

  return (
    <div>
      {/* ── Header + balance ── */}
      <div style={{ display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:14,flexWrap:"wrap",gap:8 }}>
        <h2 style={{ margin:0,fontSize:20 }}>Dashboard</h2>
        <div style={{ padding:"8px 18px",borderRadius:10,background:"rgba(79,209,197,0.1)",border:"1px solid rgba(79,209,197,0.25)",color:"var(--accent-teal)",fontFamily:"'Syne',sans-serif",fontWeight:700,fontSize:14 }}>
          Net Balance: <span style={{ color:"var(--text-primary)" }}>{fmt(totalBalance)}</span>
        </div>
      </div>

      {/* ── Smart Insights ── */}
      {insights.length > 0 && (
        <div style={{ marginBottom:16 }}>
          <div style={{ fontSize:11,fontFamily:"'Syne',sans-serif",fontWeight:700,letterSpacing:"0.07em",textTransform:"uppercase",color:"var(--text-secondary)",marginBottom:8 }}>🧠 Smart Insights</div>
          <div style={{ display:"flex",flexDirection:"column",gap:7 }}>
            {insights.map((ins,i)=>(
              <div key={i} style={{ padding:"10px 14px",borderRadius:10,fontSize:13,fontWeight:600,fontFamily:"'Syne',sans-serif",background:insightColors[ins.type],border:`1px solid ${insightBorders[ins.type]}`,color:insightText[ins.type] }}>
                {ins.icon} {ins.text}
              </div>
            ))}
          </div>
        </div>
      )}

      {/* ── Row 1: Monthly bar + Net worth area ── */}
      <div style={{ display:"grid",gridTemplateColumns:"1fr 1fr",gap:12,marginBottom:12 }} className="dash-grid-2">
        <div className="card">
          <div className="card-body">
            <p className="card-title">📅 Monthly Income vs Expense</p>
            <ResponsiveContainer width="100%" height={H}>
              <BarChart data={monthData} margin={{top:4,right:8,left:-14,bottom:0}}>
                <CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="name" tick={{fontSize:10}}/><YAxis tick={{fontSize:10}}/>
                <Tooltip content={<Tip/>}/><Legend iconSize={10} wrapperStyle={{fontSize:11}}/>
                <Bar dataKey="income"     fill="#68d391" radius={[4,4,0,0]}/>
                <Bar dataKey="expense"    fill="#fc8181" radius={[4,4,0,0]}/>
                <Bar dataKey="investment" fill="#63b3ed" radius={[4,4,0,0]}/>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
        <div className="card">
          <div className="card-body">
            <p className="card-title">📈 Cumulative Net Worth</p>
            <ResponsiveContainer width="100%" height={H}>
              <AreaChart data={netWorthData} margin={{top:4,right:8,left:-14,bottom:0}}>
                <defs>
                  <linearGradient id="nwG" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%"  stopColor="#68d391" stopOpacity={0.25}/>
                    <stop offset="95%" stopColor="#68d391" stopOpacity={0.02}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="name" tick={{fontSize:10}}/><YAxis tick={{fontSize:10}}/>
                <Tooltip content={<Tip/>}/>
                <Area type="monotone" dataKey="netWorth" stroke="#68d391" strokeWidth={2.5} fill="url(#nwG)" dot={{r:3,fill:"#68d391"}}/>
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* ── Row 2: Pie + Radar ── */}
      <div style={{ display:"grid",gridTemplateColumns:"1fr 1fr",gap:12,marginBottom:12 }} className="dash-grid-2">
        <div className="card">
          <div className="card-body">
            <p className="card-title">🍕 Expense by Category</p>
            {catExpense.length===0
              ? <div style={{ textAlign:"center",padding:"50px 0",color:"var(--text-muted)" }}>No data</div>
              : <ResponsiveContainer width="100%" height={H}>
                  <PieChart>
                    <Pie data={catExpense} cx="50%" cy="50%" innerRadius={55} outerRadius={90} paddingAngle={3} dataKey="value"
                      label={({name,percent})=>`${name} ${(percent*100).toFixed(0)}%`} labelLine={false}>
                      {catExpense.map((_,i)=><Cell key={i} fill={COLORS_PIE[i%COLORS_PIE.length]}/>)}
                    </Pie>
                    <Tooltip content={<Tip/>}/>
                  </PieChart>
                </ResponsiveContainer>
            }
          </div>
        </div>
        <div className="card">
          <div className="card-body">
            <p className="card-title">🏦 Bank Activity (Radar)</p>
            {bankData.length===0
              ? <div style={{ textAlign:"center",padding:"50px 0",color:"var(--text-muted)" }}>No data</div>
              : <ResponsiveContainer width="100%" height={H}>
                  <RadarChart data={bankData}>
                    <PolarGrid stroke="var(--border)"/>
                    <PolarAngleAxis dataKey="name" tick={{fontSize:11,fill:"var(--text-secondary)"}}/>
                    <PolarRadiusAxis tick={{fontSize:9,fill:"var(--text-secondary)"}}/>
                    <Radar name="Income"     dataKey="income"     stroke="#68d391" fill="#68d391" fillOpacity={0.18}/>
                    <Radar name="Expense"    dataKey="expense"    stroke="#fc8181" fill="#fc8181" fillOpacity={0.15}/>
                    <Radar name="Investment" dataKey="investment" stroke="#63b3ed" fill="#63b3ed" fillOpacity={0.15}/>
                    <Legend iconSize={10} wrapperStyle={{fontSize:11}}/>
                  </RadarChart>
                </ResponsiveContainer>
            }
          </div>
        </div>
      </div>

      {/* ── Row 3: Daily spend (last 30 days) ── */}
      {dayData.length > 1 && (
        <div className="card" style={{ marginBottom:12 }}>
          <div className="card-body">
            <p className="card-title">📆 Daily Expenses — Last 30 Days</p>
            <ResponsiveContainer width="100%" height={200}>
              <AreaChart data={dayData} margin={{top:4,right:8,left:-14,bottom:0}}>
                <defs>
                  <linearGradient id="dayG" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%"  stopColor="#fc8181" stopOpacity={0.25}/>
                    <stop offset="95%" stopColor="#fc8181" stopOpacity={0.02}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="date" tick={{fontSize:9}}/><YAxis tick={{fontSize:10}}/>
                <Tooltip content={<Tip/>}/>
                <Area type="monotone" dataKey="expense" name="Daily Expense" stroke="#fc8181" strokeWidth={2} fill="url(#dayG)" dot={false}/>
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>
      )}

      {/* ── Row 4: Monthly trend lines ── */}
      <div className="card" style={{ marginBottom:12 }}>
        <div className="card-body">
          <p className="card-title">📊 Monthly Trends</p>
          <ResponsiveContainer width="100%" height={200}>
            <LineChart data={monthData} margin={{top:4,right:8,left:-14,bottom:0}}>
              <CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="name" tick={{fontSize:10}}/><YAxis tick={{fontSize:10}}/>
              <Tooltip content={<Tip/>}/><Legend iconSize={10} wrapperStyle={{fontSize:11}}/>
              <Line type="monotone" dataKey="income"     stroke="#68d391" strokeWidth={2.5} dot={{r:3}}/>
              <Line type="monotone" dataKey="expense"    stroke="#fc8181" strokeWidth={2.5} dot={{r:3}}/>
              <Line type="monotone" dataKey="investment" stroke="#63b3ed" strokeWidth={2.5} dot={{r:3}}/>
            </LineChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* ── Bank-wise table ── */}
      <div className="card">
        <div className="card-body">
          <p className="card-title">🏧 Bank-wise Summary</p>
          <div className="table-responsive">
            <table className="table table-bordered table-hover">
              <thead>
                <tr>{["Bank","Income","Expense","Investment","Borrow","Borrow Return","Balance"].map(h=><th key={h}>{h}</th>)}</tr>
              </thead>
              <tbody>
                {bankData.length===0
                  ? <tr><td colSpan="7" style={{ textAlign:"center",color:"var(--text-muted)" }}>No data</td></tr>
                  : bankData.map(b=>(
                    <tr key={b.name}>
                      <td style={{ fontWeight:700 }}>{b.name}</td>
                      <td style={{ color:"var(--accent-green)" }}>{fmt(b.income)}</td>
                      <td style={{ color:"var(--accent-red)" }}>{fmt(b.expense)}</td>
                      <td style={{ color:"var(--accent-blue)" }}>{fmt(b.investment)}</td>
                      <td style={{ color:"var(--accent-purple)" }}>{fmt(b.borrow)}</td>
                      <td style={{ color:"var(--accent-teal)" }}>{fmt(b.borrowReturn)}</td>
                      <td style={{ fontWeight:800,color:b.balance>=0?"var(--accent-green)":"var(--accent-red)" }}>{fmt(b.balance)}</td>
                    </tr>
                  ))
                }
              </tbody>
            </table>
          </div>
        </div>
      </div>

      <style>{`
        @media (max-width: 640px) { .dash-grid-2{grid-template-columns:1fr!important} }
        .card-title{font-family:'Syne',sans-serif;font-weight:700;font-size:14px;color:var(--text-primary);margin-bottom:12px!important}
      `}</style>
    </div>
  );
}